const component = {
 name: "BridgeWorker",
 state: {type:"object",properties:{calls:{type:"number",default:0}}},
 references: {type:"object",properties:{mode:{type:"reference",referenceType:"variable",optional:true,label:"Режим ветви"},tree:{type:"reference",referenceType:"mechanic",optional:true,label:"Дерево поведения"},graph:{type:"reference",referenceType:"mechanic",optional:true,label:"Граф-получатель"}}},
 methods: {
 testTree:{name:"Проверить отмену BT",result:{type:"boolean"},async run({refs,engine,state,owner}){await engine.operation("sacura.variable.set",{variable:refs.mode,value:true});await engine.operation("sacura.component.start",{instance:refs.tree,methodId:"start",args:{},lifetime:"project",lifetimeOwner:owner});await engine.wait(0.6);await engine.operation("sacura.variable.set",{variable:refs.mode,value:false});await engine.wait(0.6);await engine.invoke(refs.tree,"stop",{});const stopped=state.calls;await engine.wait(5.5);await engine.operation("sacura.game.message",{message:"BT отмена: "+(state.calls===stopped?"чисто":"ОШИБКА")+"; вызовы "+stopped+"/"+state.calls});return state.calls===stopped;}},
 runGraph: {name:"Вызвать граф",result:{type:"number"},async run({refs,engine}){const value = await engine.invoke(refs.graph, "method-3358a3c1-198b-490b-b89d-60d805e6b48b", {}); await engine.operation("sacura.game.message",{message:"Код → граф → код: "+value});await engine.wait(2);return value;}},
  double: {name:"Удвоить",parameters:{type:"object",properties:{amount:{type:"number",default:4,label:"Количество"}}},result:{type:"number"},run({args,state}){state.calls++;return args.amount*2;}},
  slow: {name:"Медленная ветвь",result:{type:"boolean"},async run({engine,state}){await engine.operation("sacura.game.message",{message:"Ожидание ветви"});await engine.wait(5);state.calls++;await engine.operation("sacura.game.message",{message:"Поздняя ветвь завершилась: "+state.calls});return true;}},
  safe: {name:"Безопасная ветвь",result:{type:"boolean"},async run({engine,state}){state.calls++;await engine.operation("sacura.game.message",{message:"Безопасная ветвь: "+state.calls});await engine.wait(1);return true;}}
 }
};
